def india_code(title: str) -> str:
    return INDIACODE + quote_plus(title)


def law(id, title, category, authority, url, summary, triggers, applicability="Applicability, amendments, rules and commencement should be checked against the official source.", kind="Act"):
    return {
        "id": id,
        "title": title,
        "category": category,
        "authority": authority,
        "source_url": url,
        "summary": summary,
        "triggers": tuple(triggers),
        "applicability": applicability,
        "kind": kind,
    }


