def public_policy(policy):
    return {key: value for key, value in policy.items() if key != "triggers"}


def catalogue_payload():
    categories = sorted({item["category"] for item in POLICIES})
    return {
        "version": CATALOGUE_VERSION,
        "checked_on": CATALOGUE_CHECKED_ON,
        "count": len(POLICIES),
        "categories": categories,
        "items": [public_policy(item) for item in POLICIES],
        "notice": "Curated central-law and regulator-reference catalogue, not an exhaustive database. State/UT legislation, rules, Gazette notifications, amendments and sector-specific requirements may be missing.",
    }


def match_policies(document_text: str):
    """Return literal keyword-triggered references; no LLM or legal inference is used."""
    text = " ".join(document_text.casefold().split())
    results = []
    for policy in POLICIES:
        matched = []
        for trigger in policy["triggers"]:
            t = " ".join(trigger.casefold().split())
            if t and t in text and trigger not in matched:
                matched.append(trigger)
        if not matched:
            continue
        result = public_policy(policy)
        result["matched_terms"] = matched[:8]
        result["matched_term_count"] = len(matched)
        result["signal"] = "Multiple keyword signals" if len(matched) >= 3 else "Keyword signal"
        results.append(result)
    results.sort(key=lambda item: (-item["matched_term_count"], item["category"], item["title"]))
    return results
